-- Stage for the exact Rathe r2 baseline. See UPGRADE-CONTRACT.json.
SET @dodh_original_sql_mode=@@SESSION.sql_mode;
SET SESSION sql_mode=CONCAT_WS(',',NULLIF(@@SESSION.sql_mode,''),'STRICT_ALL_TABLES','NO_ENGINE_SUBSTITUTION');
-- Combined Darkhollow schema stage. Select the reviewed database explicitly.
-- MariaDB 10.11. DDL commits independently. Keep all writers stopped for application.
DELIMITER $$
BEGIN NOT ATOMIC
 IF DATABASE() IS NULL OR @@in_transaction<>0 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Select the reviewed database outside a transaction';
 END IF;
 IF (SELECT COUNT(*) FROM information_schema.tables
     WHERE table_schema=DATABASE() AND table_name='dodh_level69_claims')<>0 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Darkhollow claim table already exists';
 END IF;
 IF (SELECT COUNT(*) FROM information_schema.tables
     WHERE table_schema=DATABASE() AND table_type='BASE TABLE' AND engine='InnoDB'
       AND table_name IN ('inventory','character_currency','housing_inventory_sessions',
                          'completed_shared_tasks','completed_shared_task_members','kithicor_poison_custody'))<>6 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Darkhollow transactional foundation differs';
 END IF;
 IF (SELECT COUNT(*) FROM information_schema.columns
     WHERE table_schema=DATABASE() AND table_name='kithicor_poison_custody')<>27
    OR (SELECT COUNT(*) FROM information_schema.columns
        WHERE table_schema=DATABASE() AND table_name='kithicor_poison_custody'
        AND ((column_name='recipe_kind' AND column_type='tinyint(3) unsigned' AND is_nullable='NO')
          OR (column_name='recipe_context' AND data_type='mediumblob' AND is_nullable='YES')
          OR (column_name='abort_only' AND column_type='tinyint(3) unsigned' AND is_nullable='NO')))<>3
    OR (SELECT GROUP_CONCAT(column_name ORDER BY seq_in_index)
        FROM information_schema.statistics
        WHERE table_schema=DATABASE() AND table_name='kithicor_poison_custody'
          AND index_name='recipe_outbox') <> 'recipe_kind,physical,settled,request_key'
    OR (SELECT COUNT(*) FROM information_schema.statistics
        WHERE table_schema=DATABASE() AND table_name='kithicor_poison_custody'
          AND index_name='recipe_outbox')<>4 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Darkhollow custody journal shape differs';
 END IF;
 IF EXISTS(SELECT 1 FROM kithicor_poison_custody WHERE recipe_kind NOT IN(1,2,3)) THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Darkhollow journal namespace differs';
 END IF;
 CREATE TABLE dodh_level69_claims (
  character_id INT UNSIGNED NOT NULL,
  route_id TINYINT UNSIGNED NOT NULL,
  class_id TINYINT UNSIGNED NOT NULL,
  item_id INT UNSIGNED NOT NULL,
  spell_id INT UNSIGNED NOT NULL,
  item_serial INT NOT NULL COMMENT 'Positive native ItemInstance serial persisted as inventory.guid at delivery',
  PRIMARY KEY (character_id,route_id),
  CONSTRAINT dodh_level69_claim_values CHECK
   (character_id>0 AND route_id=1 AND class_id IN(2,3,4,5,6,8,10,11,12,13,14,15)
    AND item_id>0 AND spell_id>0 AND item_serial>0)
 ) ENGINE=InnoDB DEFAULT CHARSET=ascii;
END$$
DELIMITER ;
DELIMITER $$
BEGIN NOT ATOMIC
 DECLARE started BOOLEAN DEFAULT FALSE;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION
 BEGIN
   IF started THEN ROLLBACK; END IF;
   RESIGNAL;
 END;
IF DATABASE() IS NULL OR @@in_transaction<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Select the target database outside a transaction'; END IF;
IF (SELECT COUNT(*) FROM information_schema.tables
 WHERE table_schema=DATABASE() AND table_type='BASE TABLE' AND engine='InnoDB'
 AND table_name IN ('achievement_criteria', 'dodh_level69_claims', 'doors', 'dynamic_zone_templates', 'npc_types', 'reward_option_entries', 'reward_options', 'reward_sets', 'reward_sources', 'rewards', 'task_activities', 'tasks', 'tasksets', 'zone')) <> 14 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='DoDH transactional table foundation differs'; END IF;
 START TRANSACTION;
 SET started=TRUE;
IF (SELECT COUNT(*) FROM information_schema.columns
 WHERE table_schema=DATABASE() AND table_name='dodh_level69_claims')<>6
 OR NOT((SELECT GROUP_CONCAT(column_name ORDER BY seq_in_index)
 FROM information_schema.statistics WHERE table_schema=DATABASE()
 AND table_name='dodh_level69_claims' AND index_name='PRIMARY') <=> 'character_id,route_id') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='DoDH claim table shape differs'; END IF;
IF (SELECT COUNT(*) FROM `dodh_level69_claims` WHERE 1=1) <> 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='DoDH has permanent character hail claims'; END IF;
