IF (SELECT COUNT(*) FROM `completed_shared_tasks` WHERE task_id BETWEEN 920223 AND 920235) <> 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='DoDH recovery must preserve task state: completed_shared_tasks'; END IF;
IF (SELECT COUNT(*) FROM `character_tasks` WHERE taskid BETWEEN 920223 AND 920235) <> 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='DoDH recovery must preserve task state: character_tasks'; END IF;
IF (SELECT COUNT(*) FROM `character_activities` WHERE taskid BETWEEN 920223 AND 920235) <> 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='DoDH recovery must preserve task state: character_activities'; END IF;
