IF (SELECT COUNT(*) FROM `character_shared_task_reward_instances` WHERE task_id BETWEEN 920223 AND 920235) <> 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='DoDH recovery must preserve task state: character_shared_task_reward_instances'; END IF;
