-- Triangle chest loot link.
-- Review only. Database owner compares full preimage before executing.
-- Apply inside owner transaction. Roll back unless ROW_COUNT() = 1.
UPDATE npc_types AS n SET n.loottable_id = 91430
WHERE n.id = 350019 AND n.version = 1 AND n.loottable_id = 0
  AND (SELECT COUNT(*) FROM spawnentry e JOIN spawn2 s
       ON s.spawngroupID = e.spawngroupID WHERE e.npcID = 350019) = 1
  AND EXISTS (SELECT 1 FROM spawnentry e JOIN spawn2 s
              ON s.spawngroupID = e.spawngroupID
              WHERE e.npcID = 350019 AND s.id = 263181 AND s.zone = 'illsalinc' AND s.version = 1)
  AND (SELECT COUNT(*) FROM loottable_entries WHERE loottable_id = 91430) = 1
  AND EXISTS (SELECT 1 FROM loottable_entries WHERE loottable_id = 91430 AND lootdrop_id = 107021
              AND multiplier = 1 AND probability = 100 AND droplimit = 0 AND mindrop = 0)
  AND (SELECT COUNT(*) FROM lootdrop_entries WHERE lootdrop_id = 107021) = 1
  AND EXISTS (SELECT 1 FROM lootdrop_entries WHERE lootdrop_id = 107021 AND item_id = 86025
              AND chance = 100 AND multiplier = 1 AND equip_item = 1);
IF ROW_COUNT()<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='DoDH Triangle chest CAS differs'; END IF;

